package main

import (
	"errors"
	"fmt"
)

var ErrNotFound = errors.New("not found")

func get() error {
	return fmt.Errorf("get user: %w", ErrNotFound) // wraps the sentinel
}

func main() {
	err := get()
	fmt.Println(err)                         // get user: not found
	fmt.Println(errors.Is(err, ErrNotFound)) // true — walks the chain
}
